import * as T from './vendor/three.module.min.js';
export class Dirt {
 constructor(){this.points=[];for(const [x,z,r] of [[-.4,-.25,.22],[.38,.18,.19]])for(let i=0;i<48;i++){const a=i*Math.PI/24;this.points.push({x:x+Math.cos(a)*r,z:z+Math.sin(a)*r,clean:false})}for(let i=0;i<20;i++)this.points.push({x:-.08+(i%5)*.045,z:.38+Math.floor(i/5)*.04,clean:false})}
 rub(a,b){const dx=b.x-a.x,dz=b.z-a.z,l=dx*dx+dz*dz;if(l<1e-10)return;for(const p of this.points){const t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.z-a.z)*dz)/l));if(Math.hypot(p.x-a.x-dx*t,p.z-a.z-dz*t)<.16)p.clean=true}}
 get progress(){return this.points.filter(p=>p.clean).length/this.points.length}
}
export class Cleanup {
 constructor({state,canvas,onChange,onClose,sound}){Object.assign(this,{state,canvas,onChange,onClose,sound});this.active=false;this.saved=new Map();this.drag=null;
 this.scene=new T.Scene();this.scene.background=new T.Color('#d9dfd2');this.scene.add(new T.HemisphereLight(0xfff4dd,0x718575,3));const light=new T.DirectionalLight(0xffffff,3);light.position.set(-3,5,4);this.scene.add(light);this.camera=new T.OrthographicCamera(-2,2,2,-2,.1,20);this.camera.position.set(0,5,3);this.camera.lookAt(0,0,0);
 const mat=c=>new T.MeshStandardMaterial({color:c,roughness:.65});const mesh=(geo,c,x,y,z,parent=this.scene)=>{const m=new T.Mesh(geo,mat(c));m.position.set(x,y,z);parent.add(m);return m};mesh(new T.CylinderGeometry(1.05,1.05,.13,64),0xc3a075,0,-.07,0);mesh(new T.CylinderGeometry(.08,.08,1,20),0x485d4e,0,-.6,0);
 this.tray=mesh(new T.BoxGeometry(.8,.09,.65),0x527d69,.88,0,1.05);for(const [x,z,w,d]of [[.48,1.05,.045,.65],[1.28,1.05,.045,.65],[.88,.73,.8,.045],[.88,1.37,.8,.045]])mesh(new T.BoxGeometry(w,.14,d),0x315840,x,.08,z);
 this.cup=new T.Group();this.scene.add(this.cup);mesh(new T.CylinderGeometry(.16,.12,.32,32,1,true),0xfff1da,0,.18,0,this.cup);mesh(new T.CylinderGeometry(.118,.118,.02,24),0x6e4832,0,.035,0,this.cup);const rim=mesh(new T.TorusGeometry(.16,.014,8,32),0xfff1da,0,.34,0,this.cup);rim.rotation.x=Math.PI/2;mesh(new T.TorusGeometry(.1,.025,8,24),0xfff1da,.18,.18,0,this.cup);this.home=new T.Vector3(-.4,.02,-.25);
 this.cloth=mesh(new T.BoxGeometry(.3,.045,.25),0x80bdb7,0,.05,0);this.cloth.visible=false;this.dirtGroup=new T.Group();this.scene.add(this.dirtGroup);this.ray=new T.Raycaster();this.pointer=new T.Vector2();
 document.body.insertAdjacentHTML('beforeend',`<section id="cleanup" hidden aria-label="테이블 직접 정리"><header><small>HANDS ON / TABLE CARE</small><h2>다음 손님을 위한 자리</h2><button id="cleanExit">카페로 돌아가기 ↗</button></header><p id="cleanHint" role="status"></p><span id="cleanTray">컵 수거함 · 여기에 놓기</span><footer><b id="cleanProgress"></b><div class="cleanMeter"><i id="cleanBar"></i></div><p>컵을 잡아 끌어 놓고, 얼룩 위를 손가락으로 문질러요.</p><button id="cleanDone" hidden>깨끗해졌어요 · 카페로 돌아가기 →</button></footer></section>`);
 this.el=id=>document.getElementById(id);this.el('cleanExit').onclick=()=>this.close();this.el('cleanDone').onclick=()=>this.close();canvas.addEventListener('pointerdown',e=>this.down(e));canvas.addEventListener('pointermove',e=>this.move(e));canvas.addEventListener('pointerup',e=>this.up(e));canvas.addEventListener('pointercancel',e=>this.up(e,true));canvas.addEventListener('lostpointercapture',e=>this.up(e,true));window.addEventListener('blur',()=>this.cancel());document.addEventListener('visibilitychange',()=>{if(document.hidden)this.cancel()});
 }
 open(index){this.index=index;if(!this.saved.has(index))this.saved.set(index,new Dirt());this.dirt=this.saved.get(index);for(const m of [...this.dirtGroup.children]){this.dirtGroup.remove(m);m.geometry.dispose();m.material.dispose()}this.dirt.points.forEach(p=>{const m=new T.Mesh(new T.CircleGeometry(.035,10),new T.MeshBasicMaterial({color:0x74482f,transparent:true,opacity:.7,side:T.DoubleSide}));m.rotation.x=-Math.PI/2;m.position.set(p.x,.008,p.z);this.dirtGroup.add(m)});this.cup.position.copy(this.home);this.cup.visible=this.state.tables[index]==='cup'||!this.state.washCups?.find(c=>c.id===index)?.shelved;if(this.state.tables[index]!=='cup')this.cup.position.set(.88,.07,1.05);this.active=true;this.el('cleanup').hidden=false;document.body.classList.add('cleanOpen');this.resize();this.refresh()}
 close(){this.cancel();this.active=false;this.el('cleanup').hidden=true;document.body.classList.remove('cleanOpen');this.onClose()}
 cancel(){this.drag=null;this.cloth.visible=false;if(this.state.tables[this.index]==='cup')this.cup.position.copy(this.home)}
 resize(){const a=innerWidth/innerHeight,h=Math.max(1.8,1.65/a);this.camera.left=-h*a;this.camera.right=h*a;this.camera.top=h;this.camera.bottom=-h;this.camera.updateProjectionMatrix()}
 point(e,y=.02){const b=this.canvas.getBoundingClientRect();this.pointer.set((e.clientX-b.left)/b.width*2-1,1-(e.clientY-b.top)/b.height*2);this.ray.setFromCamera(this.pointer,this.camera);return this.ray.ray.intersectPlane(new T.Plane(new T.Vector3(0,1,0),-y),new T.Vector3())}
 down(e){if(!this.active||this.drag||this.state.tables[this.index]==='clean')return;const p=this.point(e);if(!p)return;const cup=this.state.tables[this.index]==='cup';if(cup&&Math.hypot(p.x-this.home.x,p.z-this.home.z)>.38){this.el('cleanHint').textContent='먼저 컵을 잡아 수거함으로 끌어주세요.';return}e.preventDefault();this.canvas.setPointerCapture(e.pointerId);this.drag={id:e.pointerId,kind:cup?'cup':'wipe',last:p};if(cup){this.cup.position.y=.28;this.sound(520,.05)}else this.cloth.visible=true}
 move(e){if(!this.active||this.drag?.id!==e.pointerId)return;const p=this.point(e);if(!p)return;if(this.drag.kind==='cup'){this.cup.position.set(T.MathUtils.clamp(p.x,-1.4,1.4),.28,T.MathUtils.clamp(p.z,-1.1,1.5));this.el('cleanHint').textContent=this.overTray()?'좋아요! 손을 떼어 수거함에 놓으세요.':'컵을 잡고 오른쪽 수거함으로 옮겨요.'}else{this.cloth.position.set(p.x,.05,p.z);this.dirt.rub(this.drag.last,p);this.refresh();if(this.dirt.progress===1&&this.state.tables[this.index]==='dirty'){const r=this.state.act('table'+this.index);if(r.ok){this.onChange();this.sound(880,.15);this.refresh()}}}this.drag.last=p}
 overTray(){return Math.abs(this.cup.position.x-.88)<.32&&Math.abs(this.cup.position.z-1.05)<.27}
 up(e,cancelled=false){if(this.drag?.id!==e.pointerId)return;if(this.drag.kind==='cup'){if(!cancelled&&this.overTray()){const r=this.state.act('table'+this.index);if(r.ok){this.cup.position.set(.88,.07,1.05);this.sound(720,.1);this.onChange()}}else this.cup.position.copy(this.home)}this.drag=null;this.cloth.visible=false;this.refresh()}
 refresh(){this.dirtGroup.children.forEach((m,i)=>m.visible=!this.dirt.points[i].clean);const status=this.state.tables[this.index],percent=Math.round(this.dirt.progress*100);this.el('cleanHint').textContent=status==='cup'?'컵을 직접 잡아 수거함에 놓아주세요.':status==='clean'?'얼룩 없이 깨끗해졌어요!':'행주로 닦듯 얼룩 위를 문질러주세요.';this.el('cleanProgress').textContent=status==='cup'?'1 / 2 · 빈 컵 수거':'2 / 2 · 얼룩 지우기 '+percent+'%';this.el('cleanBar').style.width=percent+'%';this.el('cleanDone').hidden=status!=='clean'}
 update(){const p=new T.Vector3(.88,.1,1.05).project(this.camera);this.el('cleanTray').style.left=(p.x*.5+.5)*innerWidth+'px';this.el('cleanTray').style.top=(-p.y*.5+.5)*innerHeight-65+'px'}
}
